 const straight=distance(1,0),diagonal=distance(1,1),sprint=distance(1,0,true);check('步行速度 3.8 m/s',Math.abs(straight-3.8)<.05,straight);check('斜向移动不超速',straight>3&&Math.abs(diagonal-straight)<.05,diagonal);check('冲刺速度 6.4 m/s',Math.abs(sprint-6.4)<.05,sprint);
 player.pos.set(-130,0,141);player.grounded=true;player.vy=0;input.move.x=input.move.y=0;input.pressed=k=>k==='jump';walk(1/60);input.pressed=()=>false;let maxY=player.pos.y;for(let i=0;i<100;i++){walk(1/60);maxY=Math.max(maxY,player.pos.y);}check('跳跃及落地',maxY>.8&&player.grounded&&player.pos.y===0,maxY);input.crouch=true;walk(1/60);check('蹲下眼高 1.05 m',Math.abs(camera.position.y-1.05)<.02,camera.position.y);
 input.pressed=saved.pressed;input.setGameplay(true);player.pos.set(-130,0,141);player.yaw=0;player.pitch=0;player.vy=0;player.grounded=true;dispatchEvent(new KeyboardEvent('keydown',{code:'KeyW',bubbles:true}));for(let k=0;k<60;k++){input.update(1/60);walk(1/60);input.endFrame();}dispatchEvent(new KeyboardEvent('keyup',{code:'KeyW',bubbles:true}));input.update(1/60);check('原件键盘输入 W → 移动集成',Math.abs(player.pos.z-137.2)<.06,player.pos.z);dispatchEvent(new KeyboardEvent('keydown',{code:'KeyC',bubbles:true}));input.update(1/60);walk(1/60);check('原件键盘输入 C → 蹲下集成',Math.abs(camera.position.y-1.05)<.02,camera.position.y);dispatchEvent(new KeyboardEvent('keyup',{code:'KeyC',bubbles:true}));input.setGameplay(false);input.endFrame();
