function start(){playing=true;touring=false;$('welcome').classList.add('hidden');$('settings').classList.add('hidden');$('map-panel').classList.add('hidden');mapShown=false;$('crosshair').classList.remove('hidden');input.setGameplay(true);input.requestLock();initAudio();$('hint').textContent='WASD 行走 · Shift 奔跑 · C 蹲下 · Esc 暂停';}
