$('enter').onclick=start;$('resume').onclick=start;$('menu-btn').onclick=pause;$('tour').onclick=()=>{touring=true;playing=false;$('welcome').classList.add('hidden');initAudio();$('hint').textContent='镜头漫游中 · 点击游览菜单开始步行';};$('home').onclick=()=>{teleport(landmarks[0]);start();};input.onModeChange(()=>{if(input.mode==='drag')toast('鼠标自由环顾模式 · 方向键也可转动视角');});
