function setMood(v){mood=v;const presets={dusk:{sun:0xffdfb4,int:3.3,hemi:.65,fog:0x919da2,density:.00165,ex:1.03,top:0x617b91,bottom:0xc5bca8,em:.025},morning:{sun:0xfff1da,int:3.5,hemi:.85,fog:0xaeb8ba,density:.002,ex:1.05,top:0x8da9bb,bottom:0xd1d5d2,em:.015},night:{sun:0x739bbf,int:.32,hemi:.6,fog:0x233d49,density:.0025,ex:1.05,top:0x122c45,bottom:0x546b72,em:1.6}},p=presets[v];sun.color.set(p.sun);sun.intensity=p.int;hemi.intensity=p.hemi;scene.fog.color.set(p.fog);scene.fog.density=p.density;renderer.toneMappingExposure=p.ex;skyMat.uniforms.uBrightness.value=v==='night'?.035:v==='morning'?.9:1;skyMat.uniforms.uSunDir.value.set(-65,28,-55).normalize();skyMat.uniforms.uSunCol.value.set(p.sun);skyMat.uniforms.uZen.value.set(p.top);skyMat.uniforms.uHor.value.set(p.bottom);M.glass.emissiveIntensity=p.em;M.lantern.emissiveIntensity=v==='night'?1.8:.055;scene.environmentIntensity=v==='night'?.06:.42;$('weather-label').textContent={dusk:'雨后 · 暮色',morning:'清晨 · 薄雾',night:'入夜 · 灯火'}[v];shadowUpdate();}
$('mood').onchange=e=>setMood(e.target.value);$('quality').onchange=e=>{quality=e.target.value;renderer.setPixelRatio(Math.min(devicePixelRatio,{high:1.5,medium:1,low:.75}[quality]));renderer.setSize(innerWidth,innerHeight);resizePost();reflRT.setSize(quality==='high'?1024:512,quality==='high'?576:288);groundRT.setSize(quality==='high'?768:384,quality==='high'?432:216);wetReflection.enabled.value=quality==='low'?0:1;renderer.shadowMap.enabled=quality!=='low';shadowUpdate();};$('wind').oninput=e=>U.wind.value=e.target.value/100;$('sound').onclick=()=>{initAudio();muted=!muted;$('sound').textContent=muted?'声景 关':'声景 开';};
